/* Types */
export type AcceptRequest = {
  item: string;
  project: string;
  /**
   *  An existing asset to add a version to. Without it, an asset named
   *  `name` (or the item's name) is found or created.
   */
  asset: string | null;
  name: string | null;
  /**
   *  The real size and fix-ups set in the Inbox: they replace the asset's
   *  in `prepare.json`. Left out, the asset keeps what it has. Either
   *  way an asset nobody chose a bake for skips it from now on
   *  ([`prepare::SKIP_BAKE_FROM_INBOX`]) and pads its texture edges
   *  ([`prepare::PAD_EDGES_FROM_INBOX`]): Inbox models are scans.
   */
  prep?: ModelPrep | null;
};

export type AcceptResult = {
  asset: Asset;
  version: AssetVersion;
  /**  Where the file went. */
  file: string;
  /**  The project after the change, so the Board can update. */
  project: ProjectManifest;
  /**  Why the real size and fix-ups were not saved, when they were not. */
  note: string | null;
};

export type AgentRules = {
  blenderHeadlessOnly: boolean;
  neverCaptureScreen: boolean;
  askBeforeShipping: boolean;
};

export type AgentSettings = {
  mcpEnabled: boolean;
  /**
   *  u32 rather than u16 so an out of range value reaches `validate` and
   *  gets a readable message instead of a JSON error.
   */
  mcpPort: number;
  rules: AgentRules;
};

export type AppState = {
  version: number;
  lastWorkspace: string | null;
  /**  Keyed by tool id, for example `{"blender": "/Applications/Blender.app"}`. */
  toolOverrides: Partial<{ [key in ToolId]: string }>;
  /**
   *  The bearer token agents send to the built in MCP server. Made once on
   *  first use and kept here, per machine, so it never lands in a
   *  workspace or a repo.
   */
  mcpToken?: string | null;
  /**  The By hand Downloads watcher: per machine, since folders differ. */
  downloadsWatch: DownloadsWatch;
};

/**  Something an agent asked for that waits for a yes or no in the app. */
export type Approval = {
  id: string;
  kind: ApprovalKind;
  project: string;
  /**  Ship: the run and the step it stopped before. */
  runId: string | null;
  runNumber: number | null;
  step: string | null;
  /**  Send to 3D: the provider job, its asset and settings in a few words. */
  job: string | null;
  assetName: string | null;
  service: string | null;
  detail: string | null;
  /**  A batch send: every send it holds, all approved or denied at once. */
  items: ApprovalItem[];
  requestedAtMs: number | null;
  /**  Send to 3D: the credits it should cost in all, from the price lists. */
  estimate?: number | null;
};

/**  One send of a batch approval. */
export type ApprovalItem = {
  job: string;
  assetName: string;
  /**  Its settings in a few words. */
  detail: string;
  /**  What it should cost, from the price lists. */
  estimate?: number | null;
};

/**  What an agent asked that waits for a person. */
export type ApprovalKind =
  /**  A run an agent started stopped before its Ship step. */
  | 'ship'
  /**  An agent asked to send an asset to Tripo or Meshy, which spends credits. */
  | 'send-to-3d';

/**  One file the watcher took a look at. */
export type Arrival = {
  /**  The start of its content hash. */
  id: string;
  /**  Absolute. */
  path: string;
  name: string;
  /**  The GLB inside, for a zip. */
  inner: string | null;
  bytes: number | null;
  atMs: number | null;
  state: ArrivalState;
  job: string | null;
  project: string | null;
  assetName: string | null;
  /**  Why it matched, or why it was not taken, in a few words. */
  reason: string;
  /**  The inbox file it became. */
  inboxFile: string | null;
};

/**  Where a file the watcher saw ended up. */
export type ArrivalState =
  /**  Copied into the inbox for its send. */
  | 'imported'
  /**  Waiting for you to say which asset it is. */
  | 'unmatched'
  /**  An FBX: the inbox checks read GLB, so it was left alone. */
  | 'needs-glb'
  /**  Matched, but the file could not be read as a model. */
  | 'failed'
  /**  You said it is not a model for Maquette. */
  | 'dismissed';

/**  A file a step wrote. */
export type Artifact = {
  step: string;
  /**  Relative to the pipeline root. */
  path: string;
  bytes: number | null;
};

/**  The aspect ratio asked for in the prompt. */
export type Aspect = '16:9' | '3:2' | '1:1' | '3:4' | '9:16';

export type Asset = {
  /**  Unique within the project, derived from the name. */
  id: string;
  name: string;
  kind: AssetKind;
  stage: Stage;
  status: AssetStatus;
  /**  Oldest first. */
  versions: AssetVersion[];
  /**  Relative to the project folder, with `/` separators. */
  thumbnail: string | null;
  createdAt: string;
  updatedAt: string;
};

export type AssetKind = 'prop' | 'character' | 'scene';

/**  One asset's real size and fix-ups, with what its newest model measures. */
export type AssetPrep = {
  project: string;
  asset: string;
  name: string;
  kind: AssetKind;
  entry: ModelPrep;
  /**  The newest version, when the asset has a model. */
  version: number | null;
  /**  Width, height and depth of that model as it came, metres. */
  measured: [number | null, number | null, number | null] | null;
  /**  The same after the fix-ups, once a preview of them ran. */
  fixed: [number | null, number | null, number | null] | null;
  /**  The real size scale on the fixed (else measured) model. */
  scale: number | null;
  /**  A size from the name and kind, never applied on its own. */
  suggestion: Suggestion | null;
  /**  The last preview of the entry on the newest model, when one ran. */
  report: FixupReport | null;
  defaults: FixupDefaults;
};

/**  Mirrors the kit's status chips. */
export type AssetStatus = 'done' | 'cached' | 'running' | 'failed' | 'review' | 'queued';

export type AssetVersion = {
  version: number;
  /**  Relative to the project folder, with `/` separators. */
  file: string;
  createdAt: string;
  stats: ModelStats | null;
};

/**  A change: the fields left out keep what the step has. */
export type BakePatch = {
  size: number | null;
  samples: number | null;
  denoise: boolean | null;
};

export type BakeSettings = {
  /**  The lightmap edge in pixels, one of [`SIZES`]. */
  size: number;
  /**  Cycles samples per lightmap. */
  samples: number;
  /**  Runs OpenImageDenoise over each lightmap. */
  denoise: boolean;
};

/**  A project's bake settings as the app and agents read them. */
export type BakeView = {
  settings: BakeSettings;
  /**  Whether the step's script takes the denoise flag. */
  canDenoise: boolean;
  /**  How the project's `tools/bake_light.py` compares with the shipped one. */
  script: StarterState;
  /**  The assets set to skip the bake, by id. */
  skipped: string[];
};

/**  One service's balance, or why there is none. */
export type Balance = {
  service: ProviderId;
  /**  A key is saved for this service. */
  key: boolean;
  /**  Credits left to spend. */
  credits: number | null;
  /**  Tripo: credits held by tasks still running. */
  held: number | null;
  error: string | null;
  checkedAtMs: number | null;
};

/**  An item of a batch that did not go out. */
export type BatchFailure = {
  asset: string;
  message: string;
};

/**  One asset of a batch send. */
export type BatchItem = {
  asset: string;
  /**  Per item: a prop or a character. */
  variant: PresetVariant;
  /**  Relative to the project folder, front first, at most 4. */
  images: string[];
  /**
   *  This asset's own settings, already merged over the batch preset of
   *  its variant. `None` follows the batch preset.
   */
  tripo: TripoPreset | null;
  meshy: MeshyPreset | null;
  /**  Meshy only: text that guides this asset's texture. */
  prompt?: string | null;
  /**  The earlier send of this asset it redoes. */
  redoOf?: string | null;
};

/**  One asset of the batch panel: its refs and the preset it starts from. */
export type BatchItemOptions = {
  asset: Asset;
  /**  Its own refs, front first; the batch sends these. */
  suggested: string[];
  variant: PresetVariant;
};

/**  Everything the batch Send to 3D panel needs. */
export type BatchOptions = {
  project: string;
  /**  Absolute, for the image URLs. */
  projectDir: string;
  /**  In the order asked. */
  items: BatchItemOptions[];
  keys: KeyStatus[];
};

/**
 *  Several assets to one provider: one model per asset. The settings for
 *  each variant start from the saved preset; `Some` changes them for this
 *  batch only, and an item can carry its own on top.
 */
export type BatchRequest = {
  project: string;
  provider: Provider;
  /**  For By hand: whose web app and settings. Ignored otherwise. */
  service: ProviderId;
  items: BatchItem[];
  tripoProp: TripoPreset | null;
  tripoCharacter: TripoPreset | null;
  meshyProp: MeshyPreset | null;
  meshyCharacter: MeshyPreset | null;
};

/**  What a batch send started. */
export type BatchSent = {
  batch: string;
  /**  In the order asked, one per asset. */
  jobs: ProviderJob[];
  failed: BatchFailure[];
};

export type BlendFile = {
  /**  Path relative to the scanned folder, with `/` separators. */
  file: string;
  stem: string;
  version: number | null;
};

export type BoneMap = {
  /**  The humanoid (Mixamo) name. */
  bone: string;
  /**  The rig's bone it maps to. */
  joint: string | null;
  how: BoneMatch;
};

export type BoneMatch =
  /**  The rig uses the humanoid name itself. */
  | 'exact'
  /**  A name other rigs use for that bone. */
  | 'by-name'
  | 'missing';

/**  Everything the UI needs before its first paint. */
export type Bootstrap = {
  os: HostOs;
  version: string;
  /**  Where onboarding suggests the workspace, for example `~/Maquette`. */
  defaultRoot: string;
  /**  The home folder, so the UI can show paths as `~/...`. */
  home: string | null;
  /**  The config a new workspace starts from, so the UI never keeps its own copy. */
  defaultConfig: WorkspaceConfig;
  /**  The Tripo and Meshy models the selects offer. */
  catalog: ProviderCatalog;
  workspace: WorkspaceSnapshot | null;
  /**  Set when the remembered workspace could not be opened. */
  lastWorkspaceError: string | null;
};

export type Budgets = {
  sceneMb: number | null;
  trisPerModel: number;
  /**  What the first camera stop's models may weigh, in MB. */
  firstViewMb: number | null;
};

export type BuildOutcome = {
  result: BuildResult;
  asset: Asset;
  /**  The project after the build, so the Board can update. */
  project: ProjectManifest;
  /**  The version it made, with `built`. */
  version: AssetVersion | null;
  record: BuildRecord | null;
  /**  The end of Blender's log when the build failed. */
  log: string[];
};

/**  What the last build of an asset did. */
export type BuildRecord = {
  /**  The build key of the files it ran on. */
  key: string;
  /**  RFC 3339 UTC. */
  at: string;
  /**  The version it made, or the newest one when the GLB matched it. */
  version: number | null;
  /**  Why it failed, when it did. */
  error: string | null;
  /**  The exported object names, parents first. */
  objects: string[];
  materials: string[];
  triangles: number;
  /**  The titles of the Inbox checks that did not pass. */
  warnings: string[];
};

/**  What a build did. */
export type BuildResult =
  /**  A new version. */
  | 'built'
  /**  Blender ran and made the newest version's exact bytes again. */
  | 'unchanged'
  /**  The files match the last good build; Blender did not run. */
  | 'up-to-date'
  | 'failed';

/**  What Add built asset made. */
export type BuiltAdded = {
  asset: Asset;
  project: ProjectManifest;
};

/**  One built asset as the Board and agents read it. */
export type BuiltAsset = {
  asset: string;
  name: string;
  source: BuiltSource;
  state: BuiltState;
  /**  The files of `source` that are not in the project. */
  missing: string[];
};

/**
 *  A project's built assets changed: one was added, started or finished
 *  building, so the Board reloads how they stand.
 */
export type BuiltChanged = {
  project: string;
};

/**  One built asset's script and helpers. */
export type BuiltSource = {
  /**  Relative to the project folder, for example `built/laptop.py`. */
  script: string;
  /**  The same, for the files the script imports or reads. */
  helpers: string[];
  /**
   *  The object to export with its children. Without it, the object
   *  `build()` returns, else the whole scene.
   */
  root: string | null;
  last: BuildRecord | null;
};

/**  How a built asset stands against its files. */
export type BuiltState =
  /**  Never built. */
  | 'new'
  /**  The newest version comes from these exact files. */
  | 'current'
  /**  The script, a helper or the root changed since the last build. */
  | 'stale'
  /**  The last build of these exact files failed. */
  | 'failed'
  /**  The script or a helper is gone from `built/`. */
  | 'missing'
  /**  Building now. */
  | 'building';

export type CacheInfo = {
  /**  Bytes as a JS safe number. */
  bytes: number | null;
};

/**  How an MCP call went, for the activity list. */
export type CallOutcome =
  | 'ok'
  /**  The call returned while a run waits for a shipping approval. */
  | 'waiting'
  /**  The tool reported an error. */
  | 'error'
  /**  The request had no valid token, or asked for something not served. */
  | 'refused';

export type CameraStopDef = {
  name: string;
  position: [number | null, number | null, number | null];
  target: [number | null, number | null, number | null];
  /**  Vertical field of view in degrees. */
  fov: number | null;
  /**  An absolute path to the stop's poster render, when there is one. */
  poster: string | null;
};

export type CameraStops = {
  source: StopsSource;
  /**  The file the stops were read from, relative to the project. */
  file: string | null;
  stops: CameraStopDef[];
};

/**  What Cancel would do, so the UI can say it before you press it. */
export type CancelMode =
  /**  Nothing was sent, so nothing is spent. */
  | 'free'
  /**  Meshy refunds a task that has not started; a started one refuses. */
  | 'provider'
  /**  By hand: stop waiting. */
  | 'stop-waiting'
  /**  Too late: Tripo has no cancel, or the job is over. */
  | 'none';

/**  One line of the card. */
export type CardRow = {
  label: string;
  value: string;
  /**  A short hint, for example where the setting hides. */
  note: string | null;
};

export type Check = {
  id: string;
  status: CheckStatus;
  title: string;
  detail: string | null;
  /**  One click fix-ups for what the check found, best first. */
  fixes: Fixup[];
};

export type CheckStatus = 'pass' | 'warning' | 'fail';

export type Clip = {
  /**  The animation's name in the file, or "Animation 2" without one. */
  name: string;
  /**  Its place among the file's animations. */
  index: number;
  /**  Seconds from the first key to the last. */
  duration: number | null;
  /**  Keys on its longest channel. */
  keys: number;
  /**  Frames from the first key to the last, at `fps`. */
  frames: number;
  /**  The rate its keys were sampled at. */
  fps: number | null;
  channels: number;
  /**  How many nodes it moves. */
  targets: number;
  /**  Keyframe bytes in the source model. */
  bytes: number | null;
  /**
   *  Keyframe bytes in the file the model is weighed by, when that is a
   *  build (shipped or raw); `None` when the build has no such clip yet.
   */
  shippedBytes: number | null;
  /**
   *  How far the root moves over the ground from the first key to the
   *  last, in metres; `None` for a clip that plays in place.
   */
  rootTravel: number | null;
  /**
   *  The last key matches the first (root travel aside); `None` when the
   *  keys are compressed and could not be read.
   */
  loops: boolean | null;
};

/**  What the Motion view changed about one clip. */
export type ClipSettings = {
  /**  False leaves the clip out of the shipped model. */
  ship: boolean;
};

/**  What each map group is encoded with. */
export type CodecSet = {
  color: TextureCodec;
  normal: TextureCodec;
  other: TextureCodec;
};

/**  Where a dev command came from. */
export type CommandSource =
  /**  The project's Settings. */
  | 'settings'
  /**  The site's `maquette.site.json`. */
  | 'site-config'
  /**  The site's `package.json` scripts and lockfile. */
  | 'package-json';

export type CompareKind = 'scene' | 'asset';

export type CompareSide = {
  id: string;
  /**  What the badge says first: `v7`, `Raw`, `Shipped`. */
  label: string;
  /**  What it says after: "current", "on the site", a date. */
  note: string | null;
  members: SideMember[];
};

export type Comparison = {
  id: string;
  label: string;
  kind: CompareKind;
  /**  Oldest first; the slider opens on the last two. */
  sides: CompareSide[];
};

export type CompressDefaultsView = {
  textureSize: number;
  codec: TextureCodec;
  meshopt: MeshoptLevel;
};

export type CompressPreset = {
  /**  The GLB file stem the row applies to, for example `character`. */
  model: string;
  /**  What the table shows, for example `Character`. */
  label: string;
  /**  The longest texture edge after compression, in pixels. */
  textureSize: number;
  /**
   *  An optional smaller edge for the metal, roughness, occlusion and
   *  normal maps; base color (and emissive) keep `texture_size`. Without
   *  it every map uses the one size.
   */
  dataTextureSize?: number | null;
  /**  The codec of every map group the row does not set in `map_codecs`. */
  codec: TextureCodec;
  /**
   *  Per map group codecs. Without it color and data maps use `codec` and
   *  normal maps UASTC (a locked row's normal maps keep `codec`).
   */
  mapCodecs?: MapCodecs | null;
  meshopt: MeshoptLevel;
  /**
   *  Why this row cannot change, for example "High spins her upper body".
   *  Locked rows refuse edits until the lock is removed from the file.
   */
  lock: string | null;
};

/**
 *  Where the compress step reads raw GLBs and writes the compressed ones.
 *  Each `<from>/<model>.glb` goes through the texture and meshopt passes its
 *  preset asks for and lands at `<to>/<model>.glb`.
 */
export type CompressSpec = {
  from: string;
  to: string;
};

export type Compression = {
  /**
   *  The largest texture a model may carry, checked in the Inbox and
   *  used by the compress step.
   */
  textureSize: TextureSize;
  textureCodec: TextureCodec;
  meshopt: MeshoptLevel;
};

/**  What the service reports to the UI. */
export type ConceptEvent =
  | { type: 'job'; job: ConceptJob }
  /**  A direction changed (a new image arrived). */
  | { type: 'direction'; project: string; direction: Direction };

export type ConceptImage = {
  /**
   *  Relative to the project folder, for example
   *  `concepts/porch-at-dusk/porch-at-dusk_03.png`.
   */
  file: string;
  index: number;
  width: number | null;
  height: number | null;
  starred: boolean;
  picked: boolean;
  /**  The copy in `refs/` once the image was sent there. */
  refFile: string | null;
  createdAt: string;
  /**  The object it shows, in a direction of object refs. */
  title: string | null;
};

export type ConceptJob = {
  id: string;
  runId: string | null;
  project: string;
  /**  The direction id (its folder name). */
  direction: string;
  directionName: string;
  index: number;
  /**  Where the image goes, relative to the project folder. */
  file: string;
  /**  Object refs: the object this image shows. */
  title: string | null;
  state: ConceptJobState;
  queuedAtMs: number | null;
  startedAtMs: number | null;
  finishedAtMs: number | null;
  /**  Why it failed or was stopped, or a note on how the image arrived. */
  message: string | null;
  width: number | null;
  height: number | null;
  /**  The last lines Codex printed. */
  logTail: string[];
  /**  Rate limited: when it runs again, ms since the epoch. */
  retryAtMs: number | null;
  /**  How often it ran again on its own after a rate limit. */
  retries: number;
};

export type ConceptJobState =
  | 'queued'
  | 'running'
  /**  Codex rate limited it; it runs again on its own at `retry_at_ms`. */
  | 'rate-limited'
  | 'done'
  | 'failed'
  | 'cancelled';

/**
 *  A concept job changed state or printed a line, or a direction got a new
 *  image.
 */
export type ConceptUpdate = ConceptEvent;

/**  What Copy to project did. */
export type CopiedAsset = {
  /**  The copy, in the other project. */
  asset: Asset;
  /**  The other project as it is now. */
  to: ProjectManifest;
  /**  Each old ref path and where it landed, relative to the projects. */
  refs: [string, string][];
};

/**  A plain slab the models stand on, so they cast their shadows somewhere. */
export type Desk = {
  /**  Width (X) and depth (Z) in metres. The top is at y = 0. */
  size: [number | null, number | null];
};

/**  The command that starts a site's dev server, before the port is picked. */
export type DevCommand = {
  /**  The program, then its args; `{port}` stays in place. */
  argv: string[];
  source: CommandSource;
  /**  The address the site config names, when it names one. */
  url: string | null;
  /**  For a command read from `package.json`: the manager and script. */
  manager: string | null;
  script: string | null;
  /**  The lockfile the manager came from; none means npm by default. */
  lockfile: string | null;
};

export type Direction = {
  /**  The folder name under `concepts/`. */
  id: string;
  name: string;
  prompt: string;
  /**
   *  Reference images as given: relative to the project folder or
   *  absolute.
   */
  refs: string[];
  aspect: Aspect;
  images: ConceptImage[];
  createdAt: string;
  updatedAt: string;
  /**
   *  Object refs: the concept they were taken from, relative to the
   *  project folder. `None` for an ordinary direction.
   */
  source: string | null;
  /**  Object refs: what the objects become on the Board. */
  kind: AssetKind | null;
};

/**
 *  A model file in the Downloads folder, with the send it most likely
 *  belongs to.
 */
export type DownloadMatch = {
  /**  Absolute. */
  path: string;
  name: string;
  /**  The GLB inside, for a zip. */
  inner: string | null;
  bytes: number | null;
  modifiedMs: number | null;
  /**  The waiting send it matches, if any. You confirm every match. */
  job: string | null;
  assetName: string | null;
  /**  Why it matched, in a few words. */
  reason: string | null;
};

/**
 *  The Downloads watcher took a look at a new model file: copied it into
 *  the inbox, or asks which asset it is.
 */
export type DownloadsArrival = Arrival;

/**  What Check Downloads found. */
export type DownloadsScan = {
  /**  The folder that was read. */
  folder: string;
  /**  Files changed before this are left out: the oldest waiting handoff. */
  sinceMs: number | null;
  /**  Newest first. */
  files: DownloadMatch[];
  /**  The sends waiting for a model, for choosing a match by hand. */
  waiting: ProviderJob[];
};

/**  Whether the Downloads watcher runs, and on which folder. */
export type DownloadsWatch = {
  enabled: boolean;
  /**  `None`: the system's Downloads folder. */
  folder: string | null;
};

export type Easing =
  | 'linear'
  /**  Cubic, slow at the start. */
  | 'ease-in'
  /**  Cubic, slow at the end. */
  | 'ease-out'
  | 'ease-in-out';

/**  Serializable form of [`CoreError`] for IPC. */
export type ErrorPayload = {
  code: string;
  message: string;
};

/**  How far a model's parts are spread apart at one camera stop. */
export type ExplodeKey = {
  /**  The camera stop's id. */
  stop: string;
  /**  0 together, 1 spread the whole distance. */
  amount: number | null;
};

/**  One model's explode or build-up track. */
export type ExplodeTrack = {
  /**  Metres each part moves out at an amount of 1. */
  distance: number | null;
  /**  How the amount eases from one key to the next. */
  easing: Easing;
  /**  At most one per stop, in any order; the page sorts them by stop. */
  keys: ExplodeKey[];
};

/**  What Export GLB made. */
export type ExportedModel = {
  model: string;
  /**  The raw file it replaced, relative to the project. */
  file: string;
  runNumber: number;
};

/**  How a roughness tweak treats the model's own value. */
export type FactorMode =
  /**
   *  Replaces it, and the metal and roughness map with it, so the value
   *  applies evenly.
   */
  | 'override'
  /**  Scales the factor; the map stays. */
  | 'multiply';

export type FingerWeights = {
  vertices: number;
  /**  The finger and hand joints holding flagged vertices, most first. */
  joints: JointCount[];
  /**  The distance used, in model units. */
  reach: number | null;
};

/**  What the first camera stop sees and what that costs to load. */
export type FirstView = {
  /**  The first stop's name; `None` without stops. */
  stop: string | null;
  /**  True when the stop lists its models by hand. */
  custom: boolean;
  models: FirstViewModel[];
  bytes: number | null;
  targetMb: number | null;
};

export type FirstViewModel = {
  asset: string;
  name: string;
  bytes: number | null;
  measured: Measured;
};

/**  One repair. Each kind appears at most once per asset. */
export type Fixup =
  /**  Bakes object transforms into the meshes (rigged meshes keep theirs). */
  | { op: 'apply-transforms' }
  /**
   *  Drops loose parts whose size is at most `minShare` of the model's
   *  diagonal, 0 to 0.5.
   */
  | { op: 'remove-loose'; minShare: number | null }
  /**  Joins the meshes into one, or one per material. */
  | { op: 'merge'; byMaterial: boolean }
  /**  Collapses the model down to about this many triangles. */
  | { op: 'decimate'; triangles: number }
  /**  Scales every image down to this many pixels on its longest edge. */
  | { op: 'shrink-textures'; maxSize: number }
  /**  Moves the model so its bottom centre is the origin, on the floor. */
  | { op: 'origin-bottom' };

/**  The numbers a new fix-up starts from: the workspace budgets. */
export type FixupDefaults = {
  /**  The per model triangle budget, for Decimate. */
  triangles: number;
  /**  The default texture size, for Shrink textures. */
  maxTexture: number;
  /**  For Remove loose parts. */
  looseShare: number | null;
};

/**  The kinds of fix-up, in the order they are applied. */
export type FixupKind =
  'apply-transforms' | 'remove-loose' | 'merge' | 'decimate' | 'shrink-textures' | 'origin-bottom';

/**  The fix-ups and real size of one plan on one model. */
export type FixupReport = {
  plan: ModelPrep;
  before: ModelNumbers;
  after: ModelNumbers;
  steps: FixupStep[];
  /**  The real size scale, when the plan has a size. */
  scale: number | null;
  /**  The file sizes of the model and of the fixed copy. */
  bytesBefore: number | null;
  bytesAfter: number | null;
  /**  The fixed copy, an absolute path. */
  output: string;
};

/**  What one fix-up did. */
